Stage2Game::Stage2Game()=default;
void Stage2Game::Init(){player.Reset();enemies.clear();projectiles.clear();particles.clear();combatWorld.Reset();flow=Flow::Intro;stageTime=0;combo=0;maxCombo=0;damageTaken=0;defeated=0;wave=0;arenaLocked=false;bannerTimer=1.8f;cameraX=640;boss=Grinder{};BuildStage();}
void Stage2Game::BuildStage(){for(int w=0;w<5;++w)for(const auto&s:waves[w])if(s.x>0){StreetEnemy e;e.Init({s.x,s.y,0},s.type);enemies.push_back(e);}boss=Grinder{};}
void Stage2Game::SpawnWave(int id){wave=id;arenaLocked=true;bannerTimer=1.35f;for(auto&e:enemies)e.active=false;const float lo=id==1?600:id==2?1350:id==3?2200:id==4?3250:4200;const float hi=id==1?1400:id==2?2200:id==3?3250:id==4?4200:5200;for(auto&e:enemies)if(e.position.x>=lo&&e.position.x<hi)e.Activate();}
void Stage2Game::SpawnImpact(Vector3D pos,Color color,bool heavy){const int n=heavy?28:15;for(int i=0;i<n;++i){float a=(float)i/n*2*kPi;float s=(float)GetRandomValue(80,heavy?360:230);particles.push_back({pos,{std::cos(a)*s,std::sin(a)*s},heavy?.5f:.28f,heavy?.5f:.28f,(float)GetRandomValue(3,heavy?9:6),color});}}
void Stage2Game::SpawnEnergy(){float d=player.facing==Facing::Right?1.f:-1.f;projectiles.push_back({{player.position.x+d*72,player.position.y-72,0},d*760,.9f,player.isRageMode?32:23,true});SpawnImpact({player.position.x+d*55,player.position.y-72,0},{40,210,255,255},true);}
void Stage2Game::UpdateProjectiles(float dt){for(auto&p:projectiles){if(!p.active)continue;p.pos.x+=p.vx*dt;p.life-=dt;if(p.life<=0){p.active=false;continue;}CombatBox b{p.pos.x-18,p.pos.y-18,36,36};for(auto&e:enemies)if(e.active&&!e.IsDefeated()&&b.Intersects(e.GetHurtbox())){e.TakeDamage(p.damage,{p.vx>0?420.f:-420.f,0,0});p.active=false;++combo;comboTimer=1;maxCombo=std::max(maxCombo,combo);SpawnImpact(p.pos,{50,215,255,255},true);hitstop=.1f;shake=.12f;break;}if(flow==Flow::Boss&&!boss.defeated&&p.active){CombatBox bb{boss.pos.x-70,boss.pos.y-140,140,140};if(b.Intersects(bb)&&boss.invuln<=0){boss.hp=std::max(0,boss.hp-p.damage);boss.invuln=.12f;p.active=false;++combo;comboTimer=1;maxCombo=std::max(maxCombo,combo);SpawnImpact(p.pos,{50,215,255,255},true);hitstop=.12f;shake=.16f;}}}projectiles.erase(std::remove_if(projectiles.begin(),projectiles.end(),[](const Projectile&p){return !p.active;}),projectiles.end());}
void Stage2Game::HandlePlayerHits(){if(!player.AttackIsActive()||player.hasHit||player.attackType==AttackType::Energy)return;CombatBox hit=player.GetAttackHitbox();int best=-1;float near=1e9f;for(size_t i=0;i<enemies.size();++i)if(enemies[i].active&&!enemies[i].IsDefeated()&&hit.Intersects(enemies[i].GetHurtbox())){float d=Dist(player.position,enemies[i].position);if(d<near){near=d;best=(int)i;}}if(best<0)return;auto&e=enemies[(size_t)best];int dmg=player.GetAttackDamage()+(player.isRageMode?5:0);float dir=player.facing==Facing::Right?1.f:-1.f;e.TakeDamage(dmg,{dir*player.GetAttackKnockback(),0,0});player.hasHit=true;++combo;comboTimer=1;maxCombo=std::max(maxCombo,combo);SpawnImpact(e.position,player.attackType==AttackType::Kick?Color{255,150,45,255}:Color{255,235,150,255},player.attackType==AttackType::Kick);hitstop=.08f;shake=.1f;}
void Stage2Game::HandleEnemyHits(){if(player.state==PlayerState::Defeat)return;for(auto&e:enemies)if(e.active&&!e.IsDefeated()&&!e.hasHit&&e.AttackIsActive()&&e.GetAttackHitbox().Intersects(player.GetHurtbox())){int before=player.hp;player.TakeDamage((int)e.attackDamage);damageTaken+=before-player.hp;e.hasHit=true;combo=0;comboTimer=0;SpawnImpact(player.position,{90,235,105,255},false);hitstop=.085f;shake=.12f;break;}}
void Stage2Game::EnterBoss(){arenaLocked=true;boss=Grinder{};boss.pos={5480,575,0};boss.attackTimer=.9f;flow=Flow::BossIntro;bannerTimer=2.4f;}
void Stage2Game::HandleBossHits(){if(flow!=Flow::Boss||boss.defeated||boss.invuln>0||!player.AttackIsActive()||player.hasHit||player.attackType==AttackType::Energy)return;if(player.GetAttackHitbox().Intersects({boss.pos.x-75,boss.pos.y-145,150,145})){int dmg=player.GetAttackDamage()+(player.isRageMode?8:0);boss.hp=std::max(0,boss.hp-dmg);boss.invuln=.1f;player.hasHit=true;++combo;comboTimer=1;maxCombo=std::max(maxCombo,combo);SpawnImpact(boss.pos,{255,175,55,255},true);hitstop=.12f;shake=.18f;if(boss.hp<=0)DefeatBoss();}}
void Stage2Game::UpdateCombat(float dt){if(comboTimer>0)comboTimer-=dt;else combo=0;player.Update(dt);if(player.state==PlayerState::Attack&&player.attackType==AttackType::Energy&&player.energyReleased){SpawnEnergy();player.energyReleased=false;}if(wave==0)SpawnWave(1);for(auto&e:enemies)if(e.active)e.Update(dt,player,&combatWorld);HandlePlayerHits();UpdateProjectiles(dt);HandleEnemyHits();combatWorld.Update(dt);combatWorld.ResolveHazards(player,enemies);defeated=(int)std::count_if(enemies.begin(),enemies.end(),[](const StreetEnemy&e){return e.IsDefeated();});bool cleared=true,found=false;for(auto&e:enemies){bool belongs=(wave==1&&e.position.x<1400)||(wave==2&&e.position.x>=1350&&e.position.x<2200)||(wave==3&&e.position.x>=2200&&e.position.x<3250)||(wave==4&&e.position.x>=3250&&e.position.x<4200)||(wave==5&&e.position.x>=4200&&e.position.x<5200);if(belongs){found=true;if(!e.IsDefeated())cleared=false;}}if(found&&cleared){arenaLocked=false;if(wave<5){if(player.position.x>(wave==1?1320:wave==2?2120:wave==3?3170:4120))SpawnWave(wave+1);}else if(player.position.x>5200)EnterBoss();}if(player.state==PlayerState::Defeat)flow=Flow::GameOver;}
void Stage2Game::UpdateBoss(float dt){if(boss.invuln>0)boss.invuln-=dt;if(flow==Flow::BossIntro){bannerTimer-=dt;player.position.x=std::min(player.position.x,boss.pos.x-260);if(bannerTimer<=0)flow=Flow::Boss;return;}if(boss.defeated)return;float ratio=(float)boss.hp/boss.maxHp;int ph=ratio<=.35f?3:ratio<=.70f?2:1;if(ph!=boss.phase){boss.phase=ph;boss.attack=BossAttack::Overdrive;boss.elapsed=0;SpawnImpact(boss.pos,{255,70,45,255},true);shake=.25f;}boss.attackTimer-=dt;boss.elapsed+=dt;float dx=player.position.x-boss.pos.x;if(boss.attack==BossAttack::None&&boss.attackTimer<=0){int pick=GetRandomValue(0,boss.phase==1?2:3);boss.attack=pick==0?BossAttack::Saw:pick==1?BossAttack::Slam:pick==2?BossAttack::Ram:BossAttack::Overdrive;boss.elapsed=0;boss.attackTimer=boss.phase==3?1.15f:boss.phase==2?1.45f:1.8f;}if(boss.attack==BossAttack::None&&std::abs(dx)>190)boss.pos.x+=(dx>0?1:-1)*(boss.phase==3?125.f:boss.phase==2?100.f:80.f)*dt;float tele=boss.attack==BossAttack::Ram?.42f:boss.attack==BossAttack::Slam?.55f:.32f;CombatBox hit{};bool active=false;if(boss.attack!=BossAttack::None&&boss.elapsed>=tele){if(boss.attack==BossAttack::Saw){hit={boss.pos.x-150,boss.pos.y-115,300,110};active=boss.elapsed<=tele+.25f;}else if(boss.attack==BossAttack::Slam){hit={boss.pos.x-280,boss.pos.y-85,560,100};active=boss.elapsed<=tele+.2f;}else if(boss.attack==BossAttack::Ram){boss.pos.x+=(dx>0?1:-1)*560*dt;hit={boss.pos.x-95,boss.pos.y-110,190,115};active=boss.elapsed<=tele+.42f;}else{hit={boss.pos.x-190,boss.pos.y-135,380,145};active=boss.elapsed<=tele+.32f;}}if(active&&hit.Intersects(player.GetHurtbox())&&player.state!=PlayerState::Hit){int dmg=boss.phase==3?30:boss.phase==2?25:20;int before=player.hp;player.TakeDamage(dmg);damageTaken+=before-player.hp;combo=0;comboTimer=0;SpawnImpact(player.position,{255,70,50,255},true);hitstop=.1f;shake=.2f;}if(boss.attack!=BossAttack::None&&boss.elapsed>(boss.attack==BossAttack::Ram?.95f:.85f)){boss.attack=BossAttack::None;boss.elapsed=0;}boss.pos.x=std::clamp(boss.pos.x,5100.f,5850.f);boss.pos.y=std::clamp(boss.pos.y,kLaneMinY+25.f,kLaneMaxY);HandleBossHits();if(boss.hp<=0)DefeatBoss();}
void Stage2Game::DefeatBoss(){if(boss.defeated)return;boss.defeated=true;boss.attack=BossAttack::None;flow=Flow::Clear;SpawnImpact(boss.pos,{255,155,45,255},true);shake=.45f;}
void Stage2Game::UpdateParticles(float dt){for(auto&p:particles){p.life-=dt;p.pos.x+=p.vel.x*dt;p.pos.y+=p.vel.y*dt;p.vel.x*=.92f;p.vel.y*=.92f;}particles.erase(std::remove_if(particles.begin(),particles.end(),[](const Particle&p){return p.life<=0;}),particles.end());}
void Stage2Game::Update(float dt){dt=std::min(dt,.033f);if(IsKeyPressed(KEY_ESCAPE)){if(flow==Flow::Combat||flow==Flow::Boss)flow=Flow::Pause;else if(flow==Flow::Pause)flow=boss.defeated?Flow::Clear:Flow::Combat;}if(flow==Flow::Pause){if(IsKeyPressed(KEY_R))Init();return;}if(flow==Flow::GameOver){if(IsKeyPressed(KEY_R))Init();return;}if(flow==Flow::Clear){if(IsKeyPressed(KEY_ENTER)||IsKeyPressed(KEY_J))advanceRequested=true;return;}if(hitstop>0){hitstop-=dt;return;}shake=std::max(0.f,shake-dt);bannerTimer=std::max(0.f,bannerTimer-dt);UpdateParticles(dt);if(flow==Flow::Intro){if(IsKeyPressed(KEY_ENTER)||IsKeyPressed(KEY_J))flow=Flow::Combat;return;}stageTime+=dt;if(flow==Flow::Combat)UpdateCombat(dt);if(flow==Flow::BossIntro||flow==Flow::Boss)UpdateBoss(dt);float target=std::clamp(player.position.x,640.f,kStageEnd-640.f);cameraX+=(target-cameraX)*(1-std::pow(.001f,dt));}
void Stage2Game::DrawArenaLock() const{if(!arenaLocked)return;const int arenaEnd=(int)(wave==1?1400.f:wave==2?2200.f:wave==3?3250.f:wave==4?4200.f:5200.f);const int gate=arenaEnd-8;for(int i=-2;i<=2;++i){const int x=gate+i*18;DrawRectangle(x,420,6,220,{55,180,220,145});DrawLine(x,420,x+28,390,{95,225,255,105});}}
// DF-013.2 (19-09): Grinder usa los sprites entregados (assets/bosses/grinder/).
// El arte original es pixel art pequeno (37x57 el idle) y se conserva tal cual:
// se dibuja con escala 3x exacta y filtro POINT, que es pixel-perfect.
// Todas las poses comparten la misma escala y se apoyan por los pies.
//   saw <- Saw   slam <- Slam   ram <- Ram   overdrive <- Overdrive
//   hurt <- invulnerabilidad   idle <- reposo/persecucion   death <- cargada
void Stage2Game::DrawBoss() const{
    if(!boss.pos.x||boss.defeated)return;
    const Vector2 p=boss.pos.ToScreen();
    const bool flip=player.position.x>boss.pos.x;
    const char* pose="idle";
    if(boss.invuln>0.08f)pose="hurt";
    else if(boss.attack==BossAttack::Saw)pose="saw";
    else if(boss.attack==BossAttack::Slam)pose="slam";
    else if(boss.attack==BossAttack::Ram)pose="ram";
    else if(boss.attack==BossAttack::Overdrive)pose="overdrive";
    const Texture2D tex=AssetManager::Get().GetTexture(std::string("grinder_")+pose);
    Color tint=boss.invuln>0?Color{255,190,190,255}:WHITE;
    if(boss.phase>=3&&boss.invuln<=0)tint={255,225,205,255};
    DrawEllipse((int)p.x,(int)p.y,72,14,{0,0,0,170});
    if(tex.id!=0){
        // Escala 3x exacta: el arte de Grinder es pixel art pequeno (57px de
        // alto el idle) y un factor entero mantiene la rejilla intacta. Queda
        // en ~171px, claramente por encima de Rayden (~115px).
        DrawSpriteUniform(tex,{p.x,p.y},3.0f,flip,tint,0.0f);
    }else{
        const float s=boss.phase==3?1.15f:boss.phase==2?1.08f:1.f;
        const Color body=boss.phase==3?Color{55,175,95,255}:Color{40,105,75,255};
        DrawRectangle((int)(p.x-62*s),(int)(p.y-118*s),(int)(124*s),(int)(103*s),body);
        DrawCircle((int)p.x,(int)(p.y-138*s),(int)(31*s),{25,28,30,255});
    }
    if(boss.attack==BossAttack::Overdrive)DrawCircleLines((int)p.x,(int)(p.y-70),92+std::sin((float)GetTime()*11)*8,{255,150,60,170});
}
void Stage2Game::DrawWorld() const{Camera2D c{};c.offset={640,360};c.target={cameraX,360};c.zoom=1;if(shake>0){c.target.x+=GetRandomValue(-100,100)*shake*8;c.target.y+=GetRandomValue(-100,100)*shake*5;}BeginMode2D(c);// DF-013.2: fondo propio por sector (4 escenarios del Stage 2).
 const int sc=std::clamp(wave<=1?1:wave>=4?4:wave,1,4);
 const Texture2D scenarioBg=AssetManager::Get().GetTexture(TextFormat("bg_s2_%d",sc));
 DrawScenarioBackdrop(scenarioBg,cameraX,0.35f);
 Texture2D bg=scenarioBg.id?Texture2D{0}:AssetManager::Get().GetTexture("bg_steel_deep");if(bg.id)DrawTexturePro(bg,{0,0,(float)bg.width,(float)bg.height},{cameraX-640,0,1280,720},{0,0},0,WHITE);else DrawRectangle((int)(cameraX-640),0,1280,720,{18,25,28,255});DrawRectangle(0,635,(int)kStageEnd,100,{11,14,16,255});for(int x=0;x<(int)kStageEnd;x+=160){DrawRectangle(x,620,110,12,{55,60,60,255});DrawRectangle(x+20,648,70,5,{80,70,45,255});}for(int x=180;x<(int)kStageEnd;x+=520){DrawRectangle(x,310,16,260,{24,31,34,220});DrawRectangle(x-12,320,40,8,{80,220,120,90});}DrawArenaLock();combatWorld.DrawGround();struct Item{float y;int id;};std::vector<Item>order{{player.position.y,-1}};for(size_t i=0;i<enemies.size();++i)if(enemies[i].active)order.push_back({enemies[i].position.y,(int)i});std::sort(order.begin(),order.end(),[](auto&a,auto&b){return a.y<b.y;});for(auto&i:order){if(i.id<0)player.Draw();else enemies[(size_t)i.id].Draw();}DrawBoss();for(auto&p:projectiles){Vector2 s=p.pos.ToScreen();DrawCircle((int)s.x,(int)s.y,20,{50,220,255,75});DrawCircle((int)s.x,(int)s.y,12,{110,240,255,255});}for(auto&p:particles){Vector2 s=p.pos.ToScreen();float a=p.life/p.maxLife;DrawCircle((int)s.x,(int)s.y,p.size*a,Alpha(p.color,a));}combatWorld.DrawEffects();EndMode2D();}
void Stage2Game::DrawHUD() const{ui::PlayerVitals vitals{};vitals.hp=player.hp;vitals.maxHp=player.maxHp;vitals.shield=player.shield;vitals.maxShield=player.maxShield;vitals.sp=player.sp;vitals.maxSp=player.maxSp;vitals.rage=player.rage;vitals.maxRage=player.maxRage;vitals.isRageMode=player.isRageMode;vitals.combo=combo;vitals.title="RAYDEN CRUZ // VIEJO ASTILLERO";vitals.x=16;vitals.y=14;vitals.width=500;vitals.panelHeight=132;ui::DrawPlayerVitals(vitals);DrawText(TextFormat("OLEADA %d/5",wave),1040,24,18,WHITE);if(flow==Flow::Boss||flow==Flow::BossIntro){DrawRectangle(300,18,680,48,{8,8,10,230});DrawText("GRINDER // EL SEGADOR",450,21,22,{190,255,210,255});DrawRectangle(350,50,580,12,{25,45,32,255});DrawRectangle(350,50,(int)(580.f*boss.hp/boss.maxHp),12,{70,205,115,255});DrawText(TextFormat("FASE %d",boss.phase),940,49,15,WHITE);}if(bannerTimer>0){const char*t=TextFormat("VIEJO ASTILLERO // OLEADA %d",wave);DrawText(t,640-MeasureText(t,32)/2,190,32,{185,255,215,230});}}
void Stage2Game::DrawClear() const{DrawRectangle(0,0,1280,720,{5,9,11,245});DrawText("STAGE 2 CLEAR",420,100,58,{80,220,145,255});DrawText("OLD STEEL YARD // DEEP LINE",350,170,22,WHITE);DrawText(TextFormat("TIME        %6.1fs",stageTime),380,255,23,WHITE);DrawText(TextFormat("ENEMIES     %6d",defeated),380,295,23,WHITE);DrawText(TextFormat("DAMAGE      %6d",damageTaken),380,335,23,WHITE);DrawText(TextFormat("MAX COMBO   %6d",maxCombo),380,375,23,WHITE);DrawText("BOSS        GRINDER",380,420,23,WHITE);DrawText("RANK        S",380,480,44,{255,205,70,255});DrawText("ENTER — STAGE 3: ASTRA TOWER",405,625,22,WHITE);}
void Stage2Game::Draw() const{DrawWorld();if(flow==Flow::Intro){DrawRectangle(0,0,1280,720,{5,8,12,150});DrawText("OLD STEEL YARD // DEEP LINE",315,285,40,{185,220,235,255});DrawText("ENTER / J — START",490,355,22,WHITE);}if(flow==Flow::Combat||flow==Flow::BossIntro||flow==Flow::Boss)DrawHUD();if(flow==Flow::Pause){DrawHUD();DrawRectangle(0,0,1280,720,{0,0,0,160});DrawText("PAUSED",545,235,48,WHITE);DrawText("ESC — RESUME",500,330,22,WHITE);DrawText("R — RESTART",510,375,22,WHITE);}if(flow==Flow::GameOver){DrawHUD();DrawRectangle(0,0,1280,720,{0,0,0,180});DrawText("GAME OVER",440,250,60,{235,55,65,255});DrawText("R — RESTART",500,355,22,WHITE);}if(flow==Flow::Clear)DrawClear();}
